// Tests of lane miri-tail-b's unix/virtual_socket.ts. Expected values come from the pinned Miri oracle, not from reading
// upstream: virtual_socket.oracle.txt, generated by docs/handoff/miri-tail-b-probe/run.sh.
//
// - The first test runs the real port on probe.rs end to end (fds, reads and writes in both directions, close, EOF, EPIPE,
//   non-blocking, blocking across threads with the data-race clock, epoll and poll readiness, dup) and compares its whole
//   stdout with the oracle's.
// - The others run on a stand-in `ecx`: `InterpCx.prototype` with a flat byte memory and the real `FdTable`, shims and
//   `read_from_host` / `write_to_host`, so they need no sysroot.
import { expect, test } from "bun:test";
import { existsSync, readFileSync } from "node:fs";
import { join } from "node:path";
import { miriFileCase, miriSubject } from "../../../../harness/suites.ts";
import { MIRI_SYSROOT } from "../../../../scripts/lib/miri.ts";
import { REPO } from "../../../../scripts/lib/common.ts";
import { caseEnv, mergeEnv } from "../../../../scripts/lib/env.ts";
import "../../lib.ts";
import { callback, type DynMachineCallback, type MiriInterpCx } from "../../machine.ts";
import { FdTable, FileDescriptionRef } from "../files.ts";
import { DelayedReadinessUpdates, ReadinessUpdateFlags } from "../readiness.ts";
import { type IoError, IoError_from_ErrorKind, LibcError } from "../io_error.ts";
import { VirtualSocket } from "./virtual_socket.ts";
import { Size } from "../../../rustc_abi/lib.ts";
import { InterpCx } from "../../../rustc_const_eval/interpret/eval_context.ts";
import { type InterpResult, interp_ok, Scalar } from "../../../rustc_middle/mir/interpret/mod.ts";
import { debug_InterpErrorKind } from "../../../rustc_middle/mir/interpret/error.gen.ts";
import { PLAIN } from "../../../std/fmt.ts";
import { Err, Ok, type Result } from "../../../std/result.ts";
import { InterpErrorInfo_from_InterpErrorKind } from "../../../rustc_middle/mir/interpret/mod.ts";
import { miri_fixture_expected, miri_fixture_port } from "../../../rust_ts/miri_fixture.ts";

const FIXTURE = readFileSync(join(import.meta.dir, "virtual_socket.oracle.txt"), "utf8").split("\n");
const CONST = new Map<string, number>();
for (const [, k, v] of FIXTURE.find((l) => l.startsWith("out constants "))!.matchAll(/([A-Z_a-z0-9]+)=(\d+)/g)) CONST.set(k!, Number(v));
const out_lines = FIXTURE.filter((l) => l.startsWith("out ")).map((l) => l.slice(4));
/** The oracle's stdout line starting with `prefix`, after it. */
const out = (prefix: string): string => {
  const l = out_lines.find((l) => l.startsWith(prefix));
  if (l === undefined) throw new Error(`no oracle line ${prefix}`);
  return l.slice(prefix.length).trim();
};
/** The oracle's first error line of `err_<name>.rs`, without the `error: unsupported operation: ` prefix. */
const err = (name: string): string => {
  const m = FIXTURE.find((l) => l.startsWith(`err err_${name} exit=1 `));
  if (m === undefined) throw new Error(`no oracle line for ${name}`);
  return m.replace(`err err_${name} exit=1 error: unsupported operation: `, "");
};

test("the port runs probe.rs like the oracle (stdout, stderr and exit code)", () => {
  // About a minute of CPU, and under a loaded machine it can reach the limit: only where probes are required (the gate).
  if (process.env.RUST_TS_REQUIRE_PROBES !== "1") {
    console.log("skip: probe.rs runs only with RUST_TS_REQUIRE_PROBES=1");
    return;
  }
  if (!existsSync(MIRI_SYSROOT)) throw new Error(`no Miri sysroot at ${MIRI_SYSROOT}`);
  // Run as the `miri-hello` suite runs a program file (`bun scripts/miri-diff.ts <file>` uses the same case).
  const c = miriFileCase("docs/handoff/miri-tail-b-probe/probe.rs");
  const p = Bun.spawnSync(miriSubject(c.args), { cwd: REPO, env: mergeEnv(process.env, caseEnv(c.env)) as Record<string, string> });
  const stdout = p.stdout.toString().split("\n").slice(0, -1);
  expect(stdout).toEqual(out_lines);
  expect(p.stderr.toString()).toBe("");
  expect(p.exitCode).toBe(0);
}, 600_000);

// `send` and `recv` end to end, and the paths the review's mutations reached: committed oracle fixtures (rust_ts/miri_fixture.ts).
const SOCKET_ORACLE = join(import.meta.dir, "virtual_socket_oracle");
for (const name of ["socket_ops", "recv_peek", "recv_bad_flag", "send_bad_flag"]) {
  test(`the port runs ${name}.rs like the oracle`, () => {
    if (!existsSync(MIRI_SYSROOT)) {
      if (process.env.RUST_TS_REQUIRE_PROBES === "1") throw new Error(`no Miri sysroot at ${MIRI_SYSROOT}`);
      console.log(`skip: no Miri sysroot at ${MIRI_SYSROOT}`);
      return;
    }
    const file = join(SOCKET_ORACLE, `${name}.rs`);
    expect(miri_fixture_port(file)).toEqual(miri_fixture_expected(file));
  }, 600_000);
}

// ---------------------------------------------------------------- the stand-in machine ----

class Place {
  constructor(public off: number) {}
  layout = { size: Size.from_bytes(4) };
  offset(o: Size): InterpResult<Place> {
    return interp_ok(new Place(this.off + Number(o.bytes())));
  }
}
const int = (v: number): unknown => ({ s: Scalar.from_i32(v) });
const ptr = (off: number): unknown => ({ place: new Place(off) });

interface Cx extends MiriInterpCx {
  mem: Uint8Array;
  updates: [number, ReadinessUpdateFlags][];
  blocked: { reason: unknown; cb: DynMachineCallback<unknown> }[];
  unblocked: number[];
  clocks: string[];
  i32_at(off: number): number;
}
function cx(): Cx {
  const c = Object.create(InterpCx.prototype) as Cx;
  const mem = new Uint8Array(0x50000);
  const view = new DataView(mem.buffer);
  const target = { os: { $: "Linux" } };
  const extra = {
    mem,
    updates: [] as [number, ReadinessUpdateFlags][],
    blocked: [] as { reason: unknown; cb: DynMachineCallback<unknown> }[],
    unblocked: [] as number[],
    clocks: [] as string[],
    i32_at: (off: number) => view.getInt32(off, true),
    eval_context_mut: () => c,
    tcx: { deref: () => ({ sess: { target } }) },
    machine: { fds: FdTable.init(true), delayed_readiness_updates: new DelayedReadinessUpdates([]), layouts: { i32: { size: Size.from_bytes(4) } } },
    eval_libc_i32: (name: string) => {
      const v = CONST.get(name);
      if (v === undefined) throw new Error(`no oracle constant ${name}`);
      return v;
    },
    eval_libc: (name: string) => {
      if (name === "FIONBIO") return Scalar.from_int(0x5421n, Size.from_bytes(8));
      throw new Error(name);
    },
    read_scalar: (op: { s: Scalar }) => interp_ok(op.s),
    deref_pointer_as: (op: { place: Place }) => interp_ok(op.place),
    write_scalar: (s: Scalar, p: Place) => {
      view.setInt32(p.off, Number((s as { _0: { to_bits_unchecked(): bigint } })._0.to_bits_unchecked()) | 0, true);
      return interp_ok(undefined);
    },
    read_bytes_ptr_strip_provenance: (p: number, n: Size) => interp_ok(mem.subarray(p, p + Number(n.bytes()))),
    write_bytes_ptr: (p: number, bytes: Iterable<number>) => {
      let i = p;
      for (const b of bytes) mem[i++] = b;
      return interp_ok(undefined);
    },
    release_clock: (f: (clock: { tag: string }) => void) => {
      c.clocks.push("release");
      void f;
      return interp_ok(undefined);
    },
    acquire_clock: () => {
      c.clocks.push("acquire");
      return interp_ok(undefined);
    },
    active_thread: () => 7,
    block_thread: (reason: unknown, _timeout: unknown, cb: DynMachineCallback<unknown>) => {
      c.blocked.push({ reason, cb });
    },
    unblock_thread: (t: number) => {
      c.unblocked.push(t);
      return interp_ok(undefined);
    },
    update_fd_readiness: (fd: FileDescriptionRef<unknown>, flags: ReadinessUpdateFlags) => {
      c.updates.push([fd.id()._0, flags]);
      fd.drop();
      return interp_ok(undefined);
    },
  };
  return Object.assign(c, extra);
}

/** Unwraps a shim's `InterpResult`. */
function ok<T>(r: InterpResult<T>): T {
  if (r.$ === "Err") throw new Error(`unexpected error: ${debug_InterpErrorKind(r._0.kind(), PLAIN)}`);
  return r._0;
}
/** The message of a `throw_unsup_format!`. */
const error_text = (r: InterpResult<unknown>): string => {
  if (r.$ !== "Err") throw new Error("expected an error");
  const kind = r._0.kind();
  if (kind.$ === "Unsupported" && kind._0.$ === "Unsupported") return kind._0._0;
  throw new Error(`not a throw_unsup_format!: ${debug_InterpErrorKind(kind, PLAIN)}`);
};
/** The description behind `fd`, without keeping a handle. */
function desc(c: Cx, fd: number): VirtualSocket {
  const h = c.machine.fds.get(fd)!;
  const d = h.deref() as VirtualSocket;
  h.drop();
  return d;
}
const fd_id = (c: Cx, fd: number): number => {
  const h = c.machine.fds.get(fd)!;
  const id = h.id()._0;
  h.drop();
  return id;
};
const scalar_i32 = (s: unknown): number => Number((s as { _0: { to_bits_unchecked(): bigint } })._0.to_bits_unchecked());
const BROKEN_PIPE = IoError_from_ErrorKind("BrokenPipe");
const WOULD_BLOCK = IoError_from_ErrorKind("WouldBlock");

function pipe(c: Cx, flags?: number): { r: number; w: number } {
  const pipefd = ptr(0x100);
  expect(ok(c.pipe2(pipefd as never, flags === undefined ? undefined : (int(flags) as never)))).toEqual(Scalar.from_i32(0));
  return { r: c.i32_at(0x100), w: c.i32_at(0x104) };
}
function socketpair(c: Cx, flags = 0): { a: number; b: number } {
  const ty = CONST.get("SOCK_STREAM")! | flags;
  expect(ok(c.socketpair(int(CONST.get("AF_UNIX")!) as never, int(ty) as never, int(0) as never, ptr(0x100) as never))).toEqual(Scalar.from_i32(0));
  return { a: c.i32_at(0x100), b: c.i32_at(0x104) };
}
const IO = 0x1000;
/** `read(fd, IO, n)` through the file description, as fd.rs's `read_from_fd` calls it. Returns the bytes or the error. */
function read(c: Cx, fd: number, n: number): { bytes?: number[]; err?: IoError; pending?: boolean } {
  const h = c.machine.fds.get(fd)!;
  const out: { bytes?: number[]; err?: IoError; pending?: boolean } = { pending: true };
  const finish = callback<object, Result<number, IoError>>({}, (_this, r) => {
    delete out.pending;
    if (r.$ === "Ok") out.bytes = [...c.mem.subarray(IO, IO + r._0)];
    else out.err = r._0;
    return interp_ok(undefined);
  });
  ok(h.deref().read(h, false, IO as never, n, c, finish));
  return out;
}
function write(c: Cx, fd: number, data: readonly number[]): { n?: number; err?: IoError; pending?: boolean } {
  c.mem.set(data, IO);
  const h = c.machine.fds.get(fd)!;
  const out: { n?: number; err?: IoError; pending?: boolean } = { pending: true };
  const finish = callback<object, Result<number, IoError>>({}, (_this, r) => {
    delete out.pending;
    if (r.$ === "Ok") out.n = r._0;
    else out.err = r._0;
    return interp_ok(undefined);
  });
  ok(h.deref().write(h, false, IO as never, data.length, c, finish));
  return out;
}
const bytes = (s: string): number[] => [...new TextEncoder().encode(s)];
const close = (c: Cx, fd: number): void => {
  c.machine.fds.remove(fd)!.drop();
};
/** `(n, errno, bytes)` of the oracle line as the bytes. */
const oracle_bytes = (prefix: string): number[] => JSON.parse(/\[[\d, ]*\]/.exec(out(prefix))![0]) as number[];

// ---------------------------------------------------------------- tests ----

test("fd numbers, flags of both ends (F_GETFL), and the description names", () => {
  const c = cx();
  const { r, w } = pipe(c);
  expect(`[${r}, ${w}]`).toBe(/fds=(\[.*\])/.exec(out("pipe ret="))![1]!);
  const flags = (fd: number) => scalar_i32(ok(desc(c, fd).get_flags(c)));
  expect(`r=${flags(r)} w=${flags(w)}`).toBe(out("pipe flags"));
  expect(desc(c, r).name()).toBe("pipe");
  const s = socketpair(c, CONST.get("SOCK_NONBLOCK")! | CONST.get("SOCK_CLOEXEC")!);
  expect(desc(c, s.a).name()).toBe("socketpair");
  expect(`${flags(s.a)} ${flags(s.b)}`).toBe(/flags (\d+ \d+)/.exec(out("sp nonblock"))![1]!);
});

test("`read` returns the front slice of the ring buffer: the short reads of the oracle's wrap and grow sequences", () => {
  const c = cx();
  const { r, w } = pipe(c);
  write(c, w, bytes("abcdefgh")); // capacity 8
  expect(read(c, r, 4).bytes).toEqual(oracle_bytes("wrap read"));
  write(c, w, bytes("ijk")); // wraps
  expect(read(c, r, 16).bytes).toEqual(oracle_bytes("wrap short read"));
  expect(read(c, r, 16).bytes).toEqual(oracle_bytes("wrap rest"));
  // An emptied deque resets the head.
  write(c, w, bytes("12345678"));
  expect(read(c, r, 16).bytes).toEqual(oracle_bytes("reset read"));
  // handle_capacity_increase case B.
  write(c, w, bytes("abcdefgh"));
  expect(read(c, r, 2).bytes).toEqual(oracle_bytes("case B read"));
  write(c, w, bytes("ij"));
  write(c, w, bytes("klm"));
  expect(read(c, r, 32).bytes).toEqual(oracle_bytes("case B after grow"));
  // handle_capacity_increase case C.
  write(c, w, bytes("abcdefgh"));
  write(c, w, bytes("ijklmnop"));
  expect(read(c, r, 13).bytes).toEqual(oracle_bytes("case C read"));
  write(c, w, bytes("qrstuvwxyzABC"));
  write(c, w, bytes("D"));
  expect(read(c, r, 64).bytes).toEqual(oracle_bytes("case C after grow"));
  expect(read(c, r, 64).bytes).toEqual(oracle_bytes("case C rest"));
});

test("end of file, EPIPE, EBADF, EAGAIN and zero-length operations", () => {
  const c = cx();
  const { r, w } = pipe(c);
  // Zero-length reads and writes succeed first, whatever the state.
  expect(read(c, r, 0).bytes).toEqual([]);
  expect(write(c, w, []).n).toBe(0);
  // Writing to the read end (oracle: `pipe write on read end (-1, 9)`).
  expect(write(c, r, bytes("x")).err).toEqual(LibcError("EBADF"));
  // Buffered data survives the writer's close; then EOF (oracle: `buffered`).
  expect(write(c, w, bytes("tail")).n).toBe(4);
  close(c, w);
  expect(read(c, r, 16).bytes).toEqual(oracle_bytes("buffered"));
  expect(read(c, r, 16).bytes).toEqual([]);
  // The read end after the writer closed: the upgrade fails first, so EPIPE, not EBADF
  // (oracle: `pipe write on read end after writer closed (-1, 32)`).
  expect(out("pipe write on read end after writer closed")).toBe(`(-1, ${CONST.get("EPIPE")})`);
  expect(write(c, r, bytes("x")).err).toEqual(BROKEN_PIPE);
  // The write end after the reader closed: EPIPE, but a zero-length write still succeeds.
  const p = pipe(c);
  close(c, p.r);
  expect(write(c, p.w, bytes("x")).err).toEqual(BROKEN_PIPE);
  expect(write(c, p.w, []).n).toBe(0);
  // Non-blocking (oracle: `nonblock flags .. read (-1, 11, [])`).
  const n = pipe(c, CONST.get("O_NONBLOCK")! | CONST.get("O_CLOEXEC")!);
  expect(read(c, n.r, 1).err).toEqual(WOULD_BLOCK);
});

test("a full buffer: partial write, EAGAIN, and a blocked writer woken by a read", () => {
  const c = cx();
  const n = pipe(c, CONST.get("O_NONBLOCK")!);
  // `big write (212987, 0)` then `partial write (5, 0)` then `full write (-1, 11)`.
  expect(`(${write(c, n.w, new Array<number>(0x34000 - 5).fill(7)).n}, 0)`).toBe(out("big write"));
  expect(`(${write(c, n.w, new Array<number>(16).fill(1)).n}, 0)`).toBe(out("partial write"));
  expect(write(c, n.w, bytes("x")).err).toEqual(WOULD_BLOCK);

  const p = pipe(c);
  expect(`(${write(c, p.w, new Array<number>(0x34000).fill(1)).n}, 0)`).toBe(out("fill"));
  const blocked = write(c, p.w, bytes("late"));
  expect(blocked.pending).toBe(true);
  expect(c.blocked.map((b) => b.reason)).toEqual([{ $: "VirtualSocket" }]);
  expect(desc(c, p.w).blocked_write_tid).toEqual([7 as never]);
  // The reader unblocks every blocked writer, whose callback retries.
  expect(`(${read(c, p.r, 0x10).bytes!.length}, 0)`).toBe(out("reader"));
  expect(c.unblocked).toEqual([7]);
  ok(c.blocked[0]!.cb.call(c, "Ready"));
  expect(`(${blocked.n}, 0)`).toBe(out("blocked write"));
});

test("a blocked reader is woken by a write, and the clocks are released and acquired", () => {
  const c = cx();
  const { r, w } = pipe(c);
  const blocked = read(c, r, 16);
  expect(blocked.pending).toBe(true);
  expect(desc(c, r).blocked_read_tid).toEqual([7 as never]);
  expect(c.clocks).toEqual([]);
  write(c, w, bytes("wake"));
  expect(c.clocks).toEqual(["release"]);
  expect(c.unblocked).toEqual([7]);
  ok(c.blocked[0]!.cb.call(c, "Ready"));
  expect(c.clocks).toEqual(["release", "acquire"]);
  expect(blocked.bytes).toEqual(oracle_bytes("blocked read"));
});

test("readiness updates: socket DEFAULT then peer FORCE_EDGE on a write; on a read the peer is FORCE_EDGE only once empty", () => {
  const c = cx();
  const { a, b } = socketpair(c);
  const [ida, idb] = [fd_id(c, a), fd_id(c, b)];
  write(c, a, bytes("abc"));
  expect(c.updates).toEqual([
    [ida, ReadinessUpdateFlags.DEFAULT],
    [idb, ReadinessUpdateFlags.FORCE_EDGE],
  ]);
  c.updates.length = 0;
  read(c, b, 1);
  expect(c.updates).toEqual([
    [ida, ReadinessUpdateFlags.DEFAULT],
    [idb, ReadinessUpdateFlags.DEFAULT],
  ]);
  c.updates.length = 0;
  read(c, b, 2);
  expect(c.updates).toEqual([
    [ida, ReadinessUpdateFlags.FORCE_EDGE],
    [idb, ReadinessUpdateFlags.DEFAULT],
  ]);
});

test("close: readiness, peer_lost_data and the delayed update of the peer", () => {
  const c = cx();
  const queue = c.machine.delayed_readiness_updates.to_update;
  const { a, b } = socketpair(c);
  const da = desc(c, a);
  expect(da.readiness()).toEqual({ readable: false, writable: true, read_closed: false, write_closed: false, error: false });
  write(c, b, bytes("xy")); // readable by `a`
  write(c, a, bytes("unread")); // left in `b`'s buffer
  expect(da.readiness()).toMatchObject({ readable: true, writable: true });
  // `b` closes with unread data: `a` lost data, and the update of `a` is queued, holding a strong handle of it.
  close(c, b);
  expect(queue.map((f) => f.id()._0)).toEqual([fd_id(c, a)]);
  expect(da.peer_lost_data).toBe(true);
  expect(da.readiness()).toEqual({ readable: true, writable: true, read_closed: true, write_closed: true, error: true });
  // The queue's handle keeps `a` alive through its fd's close, and releasing it closes the description.
  const weak_b_to_a = da.peer_fd_(); // `a`'s weak ref to the closed `b`
  expect(weak_b_to_a.is_closed()).toBe(true);
  close(c, a);
  queue.pop()!.drop();
  expect(queue.length).toBe(0); // `b` is gone: closing `a` queues nothing

  // A clean close loses nothing.
  const p = pipe(c);
  const [dr, dw] = [desc(c, p.r), desc(c, p.w)];
  expect(dw.readiness()).toEqual({ readable: true, writable: true, read_closed: false, write_closed: false, error: false });
  expect(dr.readiness()).toEqual({ readable: false, writable: true, read_closed: false, write_closed: false, error: false });
  close(c, p.w);
  queue.pop()!.drop();
  expect(dr.peer_lost_data).toBe(false);
  expect(dr.readiness()).toEqual({ readable: true, writable: true, read_closed: true, write_closed: true, error: false });
  const weak_w_to_r = dw.peer_fd_();
  expect(weak_w_to_r.is_closed()).toBe(false);
  close(c, p.r);
  expect(weak_w_to_r.is_closed()).toBe(true); // nothing else held `p.r`
});

test("unsupported operations: the oracle's error text", () => {
  const c = cx();
  const [AF_UNIX, SOCK_STREAM, SOCK_NONBLOCK] = [CONST.get("AF_UNIX")!, CONST.get("SOCK_STREAM")!, CONST.get("SOCK_NONBLOCK")!];
  const sp = (domain: number, ty: number, protocol: number) => error_text(c.socketpair(int(domain) as never, int(ty) as never, int(protocol) as never, ptr(0x100) as never));
  expect(sp(2, SOCK_STREAM, 0)).toBe(err("sp_domain"));
  expect(sp(-3, SOCK_STREAM, 0)).toBe(err("sp_domain_neg"));
  expect(sp(AF_UNIX, 2, 0)).toBe(err("sp_type"));
  expect(sp(AF_UNIX, 2 | SOCK_NONBLOCK, 0)).toBe(err("sp_type_flags"));
  expect(sp(AF_UNIX, SOCK_STREAM, 7)).toBe(err("sp_protocol"));
  expect(sp(-1, 2, 7)).toBe(err("sp_order"));

  const O_DIRECT = 0o40000;
  expect(error_text(c.pipe2(ptr(0x100) as never, int(O_DIRECT) as never))).toBe(err("pipe2_flags"));
  expect(error_text(c.pipe2(ptr(0x100) as never, int(O_DIRECT | CONST.get("O_NONBLOCK")!) as never))).toBe(err("pipe2_flags_mixed"));

  const { r, w } = pipe(c);
  const h = c.machine.fds.get(w)!;
  const finish = callback<object, Result<number, IoError>>({}, () => interp_ok(undefined));
  expect(error_text(h.deref().read(h, false, IO as never, 1, c, finish))).toBe(err("pipe_read_write_end"));
  const dr = desc(c, r);
  expect(error_text(dr.set_flags(0o2000, c))).toBe(err("pipe_setfl_append"));
  expect(error_text(dr.ioctl(Scalar.from_int(0x5421n, Size.from_bytes(8)), [] as never, c))).toBe(err("pipe_ioctl"));
  const { a } = socketpair(c);
  const ds = desc(c, a);
  expect(error_text(ds.ioctl(Scalar.from_int(0x1234n, Size.from_bytes(8)), [] as never, c))).toBe(err("sp_ioctl_unknown"));
});

test("metadata: the oracle's modes", () => {
  const c = cx();
  const { r, w } = pipe(c);
  const { a } = socketpair(c);
  const mode = (fd: number) => CONST.get((ok(desc(c, fd).metadata()) as { _0: string })._0);
  const [fifo, sock] = [mode(r), mode(a)];
  expect(mode(w)).toBe(fifo!);
  expect(FIXTURE.find((l) => l.startsWith("metadata pipe"))).toBe(`metadata pipe r=${fifo} w=${fifo} socketpair ${sock} ${sock}`);
});

test("as_socket: a socketpair end only; a pipe end drops its handle", () => {
  const c = cx();
  const { r } = pipe(c);
  const { a } = socketpair(c);
  const ra = c.machine.fds.get(a)!;
  expect(ra.deref().as_unix(ra).deref().as_socket(ra as never)).toBe(ra as never);
  ra.drop();
  const rr = c.machine.fds.get(r)!;
  expect(rr.deref().as_unix(rr).deref().as_socket(rr as never)).toBeUndefined();
  expect(() => rr.deref()).toThrow(); // released
});

test("send / recv: the socket paths, with the call's non-blocking flag; peeking is unsupported", () => {
  const c = cx();
  const { a, b } = socketpair(c);
  const sa = c.machine.fds.get(a)! as unknown as FileDescriptionRef<VirtualSocket>;
  const results: Result<number, IoError>[] = [];
  const finish = () =>
    callback<object, Result<number, IoError>>({}, (_t, r) => {
      results.push(r);
      return interp_ok(undefined);
    });
  // `is_non_block` applies to this call alone: nothing is buffered, so it would block otherwise.
  ok(sa.deref().recv(sa, false, IO as never, 4, false, /* is_non_block */ true, c, finish()));
  expect(results[0]).toEqual({ $: "Err", _0: WOULD_BLOCK });
  expect(desc(c, a).is_nonblock).toBe(false);
  expect(c.blocked).toEqual([]);
  c.mem.set(bytes("abcd"), IO);
  const sb = c.machine.fds.get(b)! as unknown as FileDescriptionRef<VirtualSocket>;
  ok(sb.deref().send(sb, false, IO as never, 4, false, c, finish()));
  expect(results[1]).toEqual(Ok(4));
  const sa2 = c.machine.fds.get(a)! as unknown as FileDescriptionRef<VirtualSocket>;
  expect(error_text(sa2.deref().recv(sa2, false, IO as never, 4, /* is_peek */ true, false, c, finish()))).toBe("socketpair: virtual sockets don't support peeking");
});

// ---------------------------------------------------------------- handles (review miri-tail-b N3) ----
// Every read and write path, with injected errors, then everything closed: both descriptions must be released.
const boom = () => Err(InterpErrorInfo_from_InterpErrorKind({ $: "Unsupported", _0: { $: "Unsupported", _0: "boom" } })) as never;
type Pair = { c: Cx; x: number; y: number; wx: any; wy: any };
function pair(kind: "pipe" | "sp", nonblock = false): Pair {
  const c = cx();
  let x: number, y: number;
  if (kind === "pipe") { const p = pipe(c, nonblock ? CONST.get("O_NONBLOCK")! : 0); x = p.r; y = p.w; }
  else { const p = socketpair(c, nonblock ? CONST.get("SOCK_NONBLOCK")! : 0); x = p.a; y = p.b; }
  const hx = c.machine.fds.get(x)!; const hy = c.machine.fds.get(y)!;
  const wx = FileDescriptionRef.downgrade(hx); const wy = FileDescriptionRef.downgrade(hy);
  hx.drop(); hy.drop();
  return { c, x, y, wx, wy };
}
/** Everything closed and the update queue drained: both descriptions must be gone, i.e. no handle leaked. */
function assert_released(p: Pair) {
  for (const fd of [p.x, p.y]) { const h = p.c.machine.fds.remove(fd); if (h) h.drop(); }
  const q = p.c.machine.delayed_readiness_updates.to_update;
  while (q.length) q.pop()!.drop();
  expect([p.wx.is_closed(), p.wy.is_closed()]).toEqual([true, true]);
}
const finish = () => callback<object, Result<number, IoError>>({}, () => interp_ok(undefined));
function rawread(p: Pair, fd: number, n: number) { const h = p.c.machine.fds.get(fd)!; return h.deref().read(h, false, IO as never, n, p.c, finish()); }
function rawwrite(p: Pair, fd: number, n: number) { p.c.mem.fill(1, IO, IO + Math.min(n, 0x40000)); const h = p.c.machine.fds.get(fd)!; return h.deref().write(h, false, IO as never, n, p.c, finish()); }

for (const kind of ["pipe", "sp"] as const) {
  test(`${kind}: read paths release handles`, () => {
    let p = pair(kind); ok(rawread(p, p.x, 0)); assert_released(p);                                 // zero length
    p = pair(kind, true); ok(rawread(p, p.x, 4)); assert_released(p);                               // EAGAIN
    p = pair(kind); ok(rawwrite(p, p.y, 4)); ok(rawread(p, p.x, 2)); assert_released(p);            // data, not empty
    p = pair(kind); ok(rawwrite(p, p.y, 4)); ok(rawread(p, p.x, 4)); assert_released(p);            // data, empty
    p = pair(kind); close(p.c, p.y); ok(rawread(p, p.x, 4)); (p as any).y = -1; assert_released(p); // EOF
    p = pair(kind); ok(rawwrite(p, p.y, 4)); close(p.c, p.y); ok(rawread(p, p.x, 4)); (p as any).y = -1; assert_released(p); // data, no peer
    // error paths
    p = pair(kind); ok(rawwrite(p, p.y, 4)); (p.c as any).acquire_clock = boom; expect(rawread(p, p.x, 4).$).toBe("Err"); assert_released(p);
    p = pair(kind); ok(rawwrite(p, p.y, 4)); (p.c as any).write_bytes_ptr = boom; expect(rawread(p, p.x, 4).$).toBe("Err"); assert_released(p);
    // a blocked reader: the callback holds the handle until it runs
    p = pair(kind); ok(rawread(p, p.x, 4)); expect(p.c.blocked.length).toBe(1); ok(rawwrite(p, p.y, 4)); ok(p.c.blocked[0]!.cb.call(p.c, "Ready")); assert_released(p);
  });
  test(`${kind}: write paths release handles`, () => {
    let p = pair(kind); ok(rawwrite(p, p.y, 0)); assert_released(p);                                 // zero length
    p = pair(kind); ok(rawwrite(p, p.y, 4)); assert_released(p);                                     // data
    p = pair(kind); close(p.c, p.x); ok(rawwrite(p, p.y, 4)); (p as any).x = -1; assert_released(p); // EPIPE
    p = pair(kind, true); ok(rawwrite(p, p.y, 0x34000)); ok(rawwrite(p, p.y, 1)); assert_released(p); // EAGAIN
    // error paths
    p = pair(kind); (p.c as any).release_clock = boom; expect(rawwrite(p, p.y, 4).$).toBe("Err"); assert_released(p);
    p = pair(kind); (p.c as any).read_bytes_ptr_strip_provenance = boom; expect(rawwrite(p, p.y, 4).$).toBe("Err"); assert_released(p);
    // a blocked writer
    p = pair(kind); ok(rawwrite(p, p.y, 0x34000)); ok(rawwrite(p, p.y, 1)); expect(p.c.blocked.length).toBe(1); ok(rawread(p, p.x, 16)); ok(p.c.blocked[0]!.cb.call(p.c, "Ready")); assert_released(p);
  });
  test(`${kind}: unblock_thread and update_fd_readiness errors release handles`, () => {
    let p = pair(kind); ok(rawread(p, p.x, 4));
    const un = (p.c as any).unblock_thread; (p.c as any).unblock_thread = boom; expect(rawwrite(p, p.y, 4).$).toBe("Err"); (p.c as any).unblock_thread = un;
    // the reader's callback still holds its handle; run it to release (data is there).
    ok(p.c.blocked[0]!.cb.call(p.c, "Ready")); assert_released(p);
    const real = (u: any) => (fd: any, f: any) => { fd.drop(); return boom(); };
    p = pair(kind); (p.c as any).update_fd_readiness = real(0); expect(rawwrite(p, p.y, 4).$).toBe("Err"); assert_released(p);
    p = pair(kind); ok(rawwrite(p, p.y, 4)); (p.c as any).update_fd_readiness = real(0); expect(rawread(p, p.x, 4).$).toBe("Err"); assert_released(p);
  });
}
test("EBADF and reading the write end, as_socket and peek release handles", () => {
  let p = pair("pipe"); ok(rawwrite(p, p.x, 4)); assert_released(p);          // EBADF: write on the read end
  p = pair("pipe"); expect(rawread(p, p.y, 4).$).toBe("Err"); assert_released(p); // unsup: read on the write end
  p = pair("pipe"); let h = p.c.machine.fds.get(p.x)!; expect(h.deref().as_unix(h).deref().as_socket(h as never)).toBeUndefined(); assert_released(p);
  p = pair("sp"); h = p.c.machine.fds.get(p.x)!; const s = h.deref().as_unix(h).deref().as_socket(h as never) as any; s.drop(); assert_released(p);
  p = pair("sp"); const r = p.c.machine.fds.get(p.x)! as any; expect(r.deref().recv(r, false, IO, 4, true, false, p.c, finish()).$).toBe("Err"); assert_released(p);
  p = pair("sp"); const r2 = p.c.machine.fds.get(p.x)! as any; ok(r2.deref().recv(r2, false, IO, 4, false, true, p.c, finish())); assert_released(p);
  p = pair("sp"); const w2 = p.c.machine.fds.get(p.x)! as any; ok(w2.deref().send(w2, false, IO, 4, true, p.c, finish())); assert_released(p);
});
